ITIATE_CHECKOUTS_VALUE ,b.campaign_name shopify_campaign_name ,s.total_sales ,s.total_orders ,safe_divide(shopify_revenue, count(1) over (partition by coalesce(a.date,b.date) ,lower(coalesce(a.campaign_name,b.campaign_name)) ,lower(coalesce(a.channel,b.channel)) ) ) shopify_revenue from carlton-london-wh.maplemonk.carlton_london_wh_MARKETING_CONSOLIDATED_INTERMEDIATE a left join (select date(order_date) order_date, marketplace, sum(ifnull(selling_price,0)) total_sales, count(distinct order_id) total_orders from maplemonk.carlton_london_wh_sales_CONSOLIDATED group by 1,2 ) s on date(s.order_date) = a.date and s.marketplace = (case when lower(a.ACCOUNT_NAME) like any (\'%facebook%\',\'%google%\') then \'WEBSITE\' when lower(a.ACCOUNT_NAME) like any (\'%amazon%\') then \'AMAZON\' when lower(a.ACCOUNT_NAME) like any (\'%myntra%\') then \'MYNTRA\' when lower(a.ACCOUNT_NAME) like any (\'%flipkart%\') then \'FLIPKART\' else null end) full outer join (select cast(order_timestamp as date) date ,final_utm_campaign campaign_name ,upper(case when lower(final_utm_channel) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') then \'FACEBOOK\' when lower(final_utm_channel) like (\'%google%\') then \'GOOGLE\' end) channel ,sum(total_sales) shopify_revenue from carlton-london-wh.maplemonk.carlton_london_wh_SHOPIFY_FACT_ITEMS where final_utm_channel is not null group by 1,2,3 ) b on lower(a.campaign_name) = lower(b.campaign_name) and a.date = b.date and lower(a.channel) = lower(b.channel);",
